60	Future<void> run(List<String> arguments) async {
61	  bool assertsEnabled = false;
62	  assert(() { assertsEnabled = true; return true; }());
63	  if (!assertsEnabled) {
64	    print('The analyze.dart script must be run with --enable-asserts.');
65	    exit(1);
66	  }
67	
68	  await verifyNoMissingLicense(flutterRoot);
69	  await verifyNoTestImports(flutterRoot);
70	  await verifyNoTestPackageImports(flutterRoot);
71	  await verifyGeneratedPluginRegistrants(flutterRoot);
72	  await verifyNoBadImportsInFlutter(flutterRoot);
73	  await verifyNoBadImportsInFlutterTools(flutterRoot);
74	  await verifyInternationalizations();
75	  await verifyNoTrailingSpaces();
76	
77	  // Ensure that all package dependencies are in sync.
78	  await runCommand(flutter, <String>['update-packages', '--verify-only'],
79	    workingDirectory: flutterRoot,
80	  );
81	
82	  // Analyze all the sample code in the repo
83	  await runCommand(dart,
84	    <String>[path.join(flutterRoot, 'dev', 'bots', 'analyze-sample-code.dart')],
85	    workingDirectory: flutterRoot,
86	  );
87	
88	  // Analyze all the Dart code in the repo.
89	  await _runFlutterAnalyze(flutterRoot, options: <String>[
90	    '--flutter-repo',
91	    ...arguments,
92	  ]);
93	
94	  // Try with the --watch analyzer, to make sure it returns success also.
